using System;

namespace StdbModule;

public static partial class ChineseQuotes
{
    public static class 周作人
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "別了離了象牙的塔走往十字街頭，我卻在十字街頭造起塔來住，未免似乎取巧罷？我本不是任何藝術家，沒有象牙塔或牛角的塔，自然是 standing 街頭的了，然而又有點怕累，怕擠，於是只好住在臨街的塔裡，這是自然不過的事。只是在現今中國這種態度最不上算，大眾看見塔，便說這是知識階級(就有罪)，紳士商賈看見塔在路邊，便說這是黨人(應取締)。還是如水竹村人所說「聽其自然」，不去管它好罷。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我為這兩個鬼所迷，著實吃苦不少，但在紳士的從肚臍畫一大圈及流氓的「村婦罵街」式的言語中間，也得到了不少的教訓，這總算還是可喜的。我希望這兩個鬼能夠立憲，不，希望他們能夠結婚，倘若一個是女流氓，那麼中間可以生下理想的王子來，給我們作任何種的元首。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我近來作文極慕平淡自然的景地。但是看古代或外國文學才有此種作品，自己還夢想不到有能做的一天，因為這有氣質境地與年齡的關係，不可勉強，像我這樣褊急的脾氣的人，生在中國這個時代，實在難望能夠從容鎮靜地做出平和沖淡的文章來。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我平素最討厭的是道學家(或照新式稱作法利賽人)，豈知道這正是因為自己是一個道德家的原故。我想破壞他們的偽道德，不道德的道德，其實卻同時非意識地想建設起自己所信的新的道德來。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我的興趣所在是關於生物學，人類學，兒童學與性的心理，當然是零碎的知識，但是我唯一的一點知識，所以自己不能不相當的看重，而自己所不知的乃是神學與文學的空論之類。我嘗自己發笑，難道真是從「妖精打架」會悟了道麼？道未必悟，卻總幫助了我去了解好許多問題與事情。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "不問古今中外，我只喜歡兼具健全的物理與深厚的人情之思想，混合散文的樸實與駢文的華美之文章，理想固難達到，少少具體者也就不肯輕易放過。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "用人道主義為本，對於人生諸問題，加以記錄研究的文字，便謂之人的文學。其中又可以分作兩項，(一)是正面的，寫這理想生活，或人間上達的可能性。(二)是側面的，寫人的平常生活，或非人的生活，都很可以供研究之用。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "簡明說一句，人的文學與非人的文學的區別，便在著作的態度，是以人的生活為是呢？非人的生活為是呢？", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國文學中，人的文學，本來極少。從儒教道教出來的文章，幾乎都不合格。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "人類的運命是同一的，所以我要顧慮我的運命，便同時須顧慮人類共同的運命。所以我們只能說時代，不能分中外。我們遇有創作，自然偏於見聞較確的中國一方面，其餘大多數還須介紹譯述外國的著作，擴大讀者的精神，眼裡看見了世界的人類，養成人的道德，實現人的生活。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "平民的文學正與貴族的文學相反。但這兩樣名詞，也不可十分拘泥。我們說貴族的平民的，並非說這種文學是專做貴族或平民看，專講貴族或平民的生活，或是貴族或平民自己做的。不過說文學的精神的區別，指他普遍與否，真摯與否的區別。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我們反對古文，大半原為他晦澀難解，養成國民籠統的心思，使得表現力與理解力都不發達，但別一方面，實又因為他內中的思想荒謬，於人有害的緣故。這宗儒道合成的不自然的思想，寄寓在古文中間，幾千年來，根深蒂固，沒有經過廓清，所以這荒謬的思想與晦澀的古文，幾乎已融合為一，不能分離。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "文學革命上，文字改革是第一步，思想改革是第二步，卻比第一步更為重要。我們不可對於文字一方面過於樂觀，閑卻了這一面的重大問題。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我見中國許多淫書都用白話，因此想到白話前途的危險。中國人如不真是「洗心革面」的改悔，將舊有的荒謬思想棄去，無論用古文或白話文，都說不出好東西來。就是改學了德文或世界語，也未嘗不可以拿來做「黑幕」，講忠孝節烈，發表他們的荒謬思想。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "治學術藝文者須一依自己的本性，堅持勇往，勿涉及政治的意見而改其趨向，終成為二重的生活，身心分裂，趨於毀滅，是為至要也。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我以為藝術當然是人生的，因為他本是我們感情生活的表現，叫他怎能與人生分離？「為人生」─於人生有實利，當然也是藝術本有的一種作用，但並非唯一的職務。總之藝術是獨立的，卻又原來是人性的，所以既不必使他隔離人生，又不必使他服侍人生，只任他成為渾然的人生的藝術便好了。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我以為文章的外形與內容，的確有點關係，有許多思想，既不能作為小說，又不適於作詩，便可以用論文式去表他。他的條件，同一切文學作品一樣，只是真實簡明便好。我們可以看了外國的模範做去，但是須用自己的文句與思想，不可去模仿他們。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我平常主張對於無論什麼流派，都可以受影響，雖然不可模仿；因此我於這小詩的興起，是很贊成，而且很有興趣的看著他的生長。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "做詩的人要做怎麼的詩，什麼形式，什麼內容，什麼方法，只能聽他自己完全的自由，但有一個限制的條件，便是須用自己的話來寫自己的情思。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "研究本國的古文學，不是國民的義務，乃是國民的權利。藝術上的造詣，本來要有天才做基礎，但是思想與技工的涵養也很重要，前人的經驗與積貯便是他必要的材料。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我們既然認定研究古文學為權利而非義務，所以沒有服從傳統的必要。我們讀古代文學，最妨礙我們的享樂，使我們失了正解或者墮入魔道的，是歷來那些「業儒」的人的解說，正如玉帛鐘鼓本是正當的禮樂，他們卻要另外加上一個名分的意義一般，於是在一切敘事抒情的詩文上也到處加了一層綱常名教的塗飾。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "古文學的研究，於現代文藝的形式上也有重大的利益。雖然現在詩文著作都用語體文，異於所謂古文了，但終是同一來源，其表現力之優劣在根本上總是一致，所以就古文學裡去查考前人的經驗，在創作的體裁上可以得到不少的幫助。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "阿Q這人是中國一切的「譜」──新名詞稱作「傳統」──的結晶，沒有自己的意志而以社會的因襲的慣例為其意志的人，所以在現社會是不存在而又到處存在的。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我的意見以為只應「發乎情，止乎情」，就是以戀愛之自然的範圍為範圍；在這個範圍以內我承認一切的情詩。倘若過了這界限，流於玩世或溺惑，那便是病態的病理的，在詩的價值上就有點疑問了。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我們對於情詩，當先看其性質如何，再論其藝術如何。情詩可以豔冶，但不可涉於輕薄；可以親密，但不可涉於狎褻；質言之，可以一切，只要不及於亂。這所謂亂，與從來的意思有點不同，因為這是指過分──過了情的分限，即是性的遊戲的態度，不以對手當作對等的人，自己之半的態度。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "提倡國民文學同時必須提倡個人主義。我見有些鼓吹國家主義的人對於個人主義竭力反對，不但國家主義失其根據，而且使得他們的主張有點宗教的氣味，容易變成狂信。這個結果是凡本國的必好，凡別國的必壞，自己的國土是世界的中心，自己的爭戰是天下的正義，而猶稱之曰「自尊心」。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我不知怎地很為遺傳學說所迫壓，覺得中國人總還是中國人，無論是好是壞，所以保存國粹正可不必，反正國民性不會消滅，提倡歐化也是虛空，因為天下不會有兩粒豆那樣相似的民族，叫他怎麼化得過來。現在要緊的是喚起個人的與國民的自覺，盡量地研究介紹今古的文化，讓它自由地滲進去，變成民族精神的滋養料，因此可望自動地發生出新漢族的文明來。這是我任意的夢想，也就是我所以贊成國民文學的提倡之理由。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我們平常專憑理性，議論各種高上的主義，覺得十分徹底了，但感情不曾改變，便永遠只是空言空想，沒有實現的時候。真正的文學能夠傳染人的感情，他固然能將人道主義的思想傳給我們，也能將我們的主見思想，從理性移到感情這方面，在我們的心的上面，刻下一個深的印文，為從思想轉到事實的樞紐。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我常這樣想，現代的散文在新文學中受外國的影響最少，這與其說是文學革命的還不如說是文藝復興的產物，雖然在文學發達的程度上復興與革命是同一樣的進展。在理學與古文沒有全盛的時候，抒情的散文也已得到相當的長發，不過在學士大夫的眼中自然也不很看得起；我們讀明清有些名士派的文章，覺得與現代文學的情趣幾乎一致，思想上固然難免有若干距離，但如明人所表示的對於禮法的反動則又很有現代的氣息了。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我覺得新詩的成就上有一種趨勢恐怕很是重要，這便是一種融化。不瞞大家說，新詩本來也是從模仿來的。他的進化在於模仿與獨創之消長，近來中國的詩似乎有漸近於獨創的模樣，這就是我所謂的融化。自由之中自有節制，豪華之中實含清澀，把中國文學固有的特質因了外來文化的影響而益美化，不可只披上一件呢外套就了事。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國的文學革命是古典主義(不是擬古主義)的影響，一切作品都像是一個玻璃球，晶瑩透澈得太厲害了，沒有一點兒朦朧，因此也似乎缺少一種餘香與回味。正當的道路恐怕還是浪漫主義──凡詩差不多無不是浪漫主義的，而象徵實在是其精意。這是外國的潮流，同時也是中國的舊手法；新詩如往這一路去，融合便可成功，真正的中國新詩也就可以產生出來了。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我常想，文學即是不革命，能革命就不必需要文學及其他種種藝術或宗教，因為他已有了他的世界了；接著吻的嘴不再要唱歌，這理由正是一致。但是，假如征服了政治的世界，而在別的方面還有不滿，那當然還有要到藝術世界裡去的時候，拿破侖在軍營中帶著《維特的煩惱》可以算作一例。文學所以雖是不革命，卻很有他的存在的權利與必要。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "這新時代的文學家是偶像破壞者，但他還有他的新宗教──人道主義的理想是他的信仰，人類的意志便是他的神。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我想現在講文藝，第一重要的是「個人的解放」，其餘的主義可以隨便。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "當自己求自由發展時，對於壓迫的勢力，不應取忍受的態度；當自己成了已成勢力之後，對於他人的自由發展，不可不取寬容的態度。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "文藝的生命是自由不是平等，是分離不是合併，所以寬容是文藝發達的必要條件。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "不能以多數決的方法來下文藝的判決。君師的統一思想，定於一尊，固然應該反對；民眾的統一思想，定於一尊，也是應該反對的。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我們切不可崇拜祖先，也切不可望子孫崇拜我們。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國現在假道學的空氣濃厚極了，官僚和老頭子不必說，就是青年也這樣，如批評心琴畫會展覽云：「絕無一幅裸體畫，更見其人品之高矣！」中國之未曾發昏的人們何在，為什麼還不拿了「十字架」起來反抗？我們當從藝術科學尤其是道德的見地，提倡淨觀，反抗這假道學的教育，直到將要被火烤了為止。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我們希望中國性道德的整飭，也就不希望訓條的增加，只希望知識的解放與趣味的修養。科學之光與藝術之空氣，幾時才能侵入青年的心裏，造成一種新的兩性觀念呢？", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我相信要了解中國須得研究禮教，而要了解禮教更非從薩滿教入手不可。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "改良農村的最大阻力，便在鄉人們自身的舊思想，這舊思想的主力是道教思想。所謂道教，不是指老子的道家者流，乃是指張天師做教主，有道士們做祭司的，太上老君派的拜物教。平常講中國宗教的人，總說有儒釋道三教，其實儒教的綱常早已崩壞，佛教也只剩了輪迴因果幾件和道教同化了的信仰還流行民間，支配國民思想的已經完全是道教的勢力了。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "嗚呼，烈士殉國，於委蛻更有何留戀，苟有利於國人，當不惜舉之以遣之耳。然則國人此舉既得烈士之心，又能廢物利用，殊無可以非議之處，而且順應潮流，改良吃法，尤為可喜，西人嘗稱中國人為精於吃食的國民。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國人因為奴性尚未退化；喜因而惡創，善記憶或缺乏思索，雖然獲得新知識也總是堆積起來，不能活用，古希臘哲人云：「多識不能益智」，正是痛切的批評。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國的知識大抵如此，我常說這好像一家藥材店，架上許多抽屜貯藏著各種藥品，一格一格的各不相犯，烏頭、附子與茯苓，生地間壁放著，待有主顧時取用。中國人的腦子裡也分作幾隔，事實與迷信同時並存，可以學過生理的人在講臺上教骨頭有幾塊，生病時便相信符水可以止痢，石燕可以催生，而靜坐起來「丹田」裡有一股氣可以穿過橫隔膜，鑽通顱骨而出去了。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國人似未知生命之重。故不知如何善捨其生命，而又隨時隨地被奪其生命而無所愛惜。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國人對於飲食還知道一點享用之術，但是一般的生活之藝術卻早已失傳了。中國生活的方式現在只是兩個極端，非禁欲即是縱欲，非連酒字都不準說即是浸身在酒槽裡，二者互相反動，各益增長，而其結果則是同樣的汙糟。動物的生活本有自然的調節，中國在千年以前文化發達，一時頗有臻於靈肉一致之象，後來為禁欲思想所戰勝，變成現在這樣的生活，無自由，無節制，一切在禮教的面具底下實行迫壓與放恣，實在所謂禮者早已消滅無存了。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國現在所切要的是一種新的自由與新的節制，去建造中國的新文明，也就是復興千年前的舊文明，也就是與西方文化的基礎之希臘文明相合一了。這些話或者說的太大太高了，但據我想捨此中國別無得救之道，宋以來的道學家的禁欲主義總是無用的了，因為這只足以助成縱欲而不能收調節之功。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國人所最歡迎的東西，大約無過於賣國賊，因為能夠介紹他們去給異族做奴隸，其次才是自己能夠作賤他們奴使他們的暴君。我們翻開正史野史來看，實在年代久遠了，奴隸的癮一時難以戒絕，或者也是難怪的，──但是此後卻不能再任其猖獗了。照現在這樣下去，不但民國不會實現，連中華也頗危險。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國往往大家都知道非和不可，等到和了，大家從避難回來，卻熱烈地崇拜主戰者，稱岳飛而罵秦檜，稱翁同龢、劉永福而痛罵李鴻章，皆是也。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國人近來大講東方文化和西方文化，然而專門研究某一種文化的人終於沒有，所以都說的不得要領。所謂西方文化究竟以哪一國為標準，東方文化究竟是中國還是印度為主呢？現代的情狀固然重要，但是重要的似乎在推究一點上去，找尋他的來源。我想中國的，印度的，以及歐洲之根源的希臘的文化，都應該有專人研究，綜合他們的結果，再行比較，才有議論的可能，一切轉手的引證全是不可憑信。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "為現代的新青年計，人生的基本知識是必要的，主要就是這幾種科學：一、自然科學類，內有天文學、地質學、生物學三種。二、社會科學類，內只有人類學一種，但包含歷史等在內。一眼看去，這都是專門學問，非中學課程中所有，要望青年男女得到這種知識，豈非夢話。這個情形我原是知道的，不過我的意思是只要了解大意便好，並不是專攻深造，大約不是很難的事。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "查明同類之狂妄和愚昧，與思索個人的老死病苦，一樣是偉大的事業，積極的人可以當一種重大的工作，在消極的也不失為一種有趣的消遣，虛空盡由他虛空，知道他是虛空，而又偏去追蹤，去查明，那麼這是很有意義的，這實在可以當得起說是偉大的捕風。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "八股文不但是集合古今駢散的菁華，凡是從漢字的特別性質演出的一切微妙的遊藝也都包括在內，所以我們說它是中國文學的結晶，實在是沒有一絲一毫的虛價。民國初年的文學革命，據我的解釋，也原是對於八股文化的一個反動，世上許多褒貶都不免有點誤解，假如想了解這個運動的意義而不先明瞭八股是什麼東西，那猶如不知道清朝歷史的人想懂得辛亥革命的意義，完全是不可能了。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "吳稚暉公說過，中國有土八股，有洋八股，有黨八股，我們在這裡覺得未可以人廢言。在這些八股做著的時候，大家還只是舊日的士大夫，雖然身上穿著洋服，嘴裡咬著雪茄。要想打破一點這樣的空氣，反省是最有用的方法，趕快去查考祖先的窗稿，拿來與自己的大作比較一下，看看土八股究竟死了沒有，是不是死了之後還是奪舍投胎地復活在我們自己的心裡。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "要講人道，愛人類，便須先使自己有人的資格，占得人的位置。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "個人愛人類，就只為人類中有了我，與我相關的緣故。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我相信必須個人對自己有了一種了解,才能立定主意去追求正當的人的生活.希臘哲人，希臘哲人達勒思(Thales)的格言说道，‘知道你自己’( Gnothi seauton)可以说是最好的教训。我所主张的常识，便即是使人們‘知道你自己’的工具。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "有些人把生活也分作片段，僅想選取其中的幾節，將不中意的梢頭棄去。這種辦法可以稱之曰抽刀斷水，揮劍斬雲。生活中大抵包含飲食、戀愛、生育、工作、老死這幾樣事情，但是聯結在一起，不是可以隨便選取一二的。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我並不以為人可以終日睡覺或用茶酒代飯吃，然而我覺得睡覺或飲酒喝茶不是可輕蔑的事，因為也是生活之一部份。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我們於日用必需的東西以外，必須還有一點無用的遊戲與享樂，生活才覺得有意思。我們看夕陽，看花，聽雨，聞香，喝不求解渴的酒，吃不求飽的點心，都是生活上必要的──雖然是無用的裝點，而且是愈精煉愈好。可憐現在的中國生活，卻是極端地乾燥粗鄙，別的不說，我在北京徬徨了十年，終未曾吃到好點心。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我們哀悼死者，並不一定是在體察他滅亡之悲哀，實在多是引動追懷，痛切地發生今昔存歿之感。無論怎樣地相信神滅，或是厭世，這種感傷恐終不易擺脫。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "本來人生是一貫的，其中卻分幾個段落，如童年、少年、中年、老年，各有意義，都不容空虛。譬如少年時代是浪漫的，中年是理智的時代，到了老年差不多可以說是待死堂的生活罷。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我覺得人之互相理解是至難──即使不是不可能的事，而表現自己之真實的感情思想也是同樣地難，我們說話作文，聽別人的話，讀別人的文，以為互相理解了，這是一個聊以自娛之如意的好夢，好到連自己覺到了的時候也還不肯立即承認，知道是夢了卻還想在夢境中多流連一刻……", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "為現代的新青年計，人生的基本知識是必要的，大要就是這幾種學科:一、自然科學類，內有天文學，地質學，生物學三種。二、社會科學類，內只人類學一種，但包含歷史等在內。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中國自五四以來，高唱群眾運動社會制裁，到了今日變本加厲，大家忘記了自己的責任，都來干涉別人的事情，還自以為是頭號的新文化，真是可憐憫者。我想現在最要緊的是提倡個人解放，凡事由個人自己負責去做，自己去解決，不要閑人在旁吆喝叫打。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "現在所有的國粹主義的運動大抵是對於新文學的一種反抗，但我推想以後要改變一點色彩，將成為國家的傳統主義，即是包含一種對於異文化的反抗的意義：這個是好是壞我且不說，但我相信這也是事實。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "請願的事只有在現今的立憲國裡，還暫時勉強應用，其餘的地方都不通用了。例如俄國，在一千九百零幾年，曾因此而有軍警在冬宮前開炮之舉，碰的更利害了。但他們也就從此不再請願了。……我希望中國請願也從此停止，各自去努力吧。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "赤化灰化，有些學界名流和新聞記者還在那裡誣陷。白死白死，所謂革命政府與帝國主義原是一樣東西。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "我並不想抹殺男子，以為他們不配負救國之責，但他們之不十分有生氣，不十分從容而堅忍，那是無可諱言的。我也並不如日本記者那樣以為女子之力即足以救中國，但我確信中國革命如要成功，女子之力必得佔其大半。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "普通總覺得南京與北京有點不同，青年學生跑去不知世故地行動，卻終於一樣地被禍，有的還從北方逃出去投在網裡，令人不能不感到憐憫。至於那南方的殺人者是何心理狀態，我們不得而知，只覺得驚異；倘若這是軍閥的常態，那這驚異也將消失，大家唯有復歸於沉默，於是而沉默遂統一中國南北。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "現在知識階級應做的事業，一部份的去弄學問藝術、改革思想，一部份「往民間去」，一部份特別有才力，「膽智不凡」的尤須「往兵裡去」；清末革命的先烈這樣的做過了。民國一成立，大家都寬心，以為天下從此長治久安，都去談文化，其實這也只是做文官的敲門磚，將武力交給一班張三李四，「太阿倒持」，反受欺凌，正是怨不得別人。現在覺悟的時期應當到了；兵是要緊的。大人(即兵頭)也要我們自己做。那時我們才會有自由。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "崇拜孫中山先生的自然還從三民五權上去著力進行，我的意見則此刻還應特別注重民族主義，拔去國民的奴氣惰性，百事才能進步，否則仍然是路柳牆花，賣身度日，孫中山先生把他從滿人手中救出，不久他還爬到什麼國的腳下去了。「不幸而吾言中，不聽則國必亡！」", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "近六年來差不多天天怕反動運動之到來，而今也終於到來了，殊有康聖人的「不幸而吾言中」之感。這反動是什麼呢？不一定是守舊復古，凡統一思想的棒喝主義即是。北方的「討赤」不必說了，即南方的「清黨」也是我所怕的那種反動之一，因為他所問的並不是都是行為罪而是思想罪──以思想殺人，這是我所覺得最恐怖的。中國如想好起來，必須立即停止這個殺人勾當，使政治經濟宗教藝術上的各新派均得自由地思想與言論才好。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "清醒地都看見聽見，又無力高聲大喊，此乃是凡人的悲哀。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "中日共存的理論是對的，不過他的前提是先要中國有排日的決心與毅力，沒有這個，共存就是合併。", Author = "周作人" },
            new Quote { Id = "https://zh.wikiquote.org/wiki/周作人", Text = "日本天天大叫「日支共榮共存」，其實即是侵略的代名詞。", Author = "周作人" },
        };
    }
}